type Farmer = {
  id?: string;
  name?: string;
  email?: string;
  phone?: string;
  role?: string;
};

type Stats = {
  total_farms?: number;
  total_crops?: number;
  active_listings?: number;
  pending_orders?: number;
  total_income?: number;
};

type Weather = {
  temperature?: number;
  condition?: string;
  humidity?: number;
  rain_probability?: number;
};

type Crop = {
  id?: string;
  name?: string;
  crop_name?: string;
  status?: string;
  quantity?: number;
};

type Alert = {
  id?: string;
  title?: string;
  message?: string;
  type?: string;
  created_at?: string;
};

type DashboardData = {
  farmer?: Farmer;
  stats?: Stats;
  weather?: Weather;
  recent_crops?: Crop[];
  recent_orders?: unknown[];
  alerts?: Alert[];
};

type DashboardResponse = {
  success?: boolean;
  data?: DashboardData;
};

type OrderStatus = "pending" | "accepted" | "rejected" | "completed" | "cancelled";

type FarmerOrder = {
  id: string;
  listing_id?: string;
  buyer_id?: string;
  total_amount?: number;
  status: OrderStatus;
  created_at?: string;
  items?: Array<{
    id?: string;
    crop_id?: string;
    quantity_kg?: number;
    price_per_kg?: number;
  }>;
};

type SpeechRecognitionEventLike = {
  results: {
    [index: number]: {
      [index: number]: {
        transcript: string;
      };
    };
  };
};

type SpeechRecognitionLike = {
  lang: string;
  interimResults: boolean;
  continuous: boolean;
  onresult: ((event: SpeechRecognitionEventLike) => void) | null;
  onerror: (() => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
};

type SpeechRecognitionConstructor = new () => SpeechRecognitionLike;

function getToken() {
  if (typeof window === "undefined") return null;
  return localStorage.getItem("access_token") || localStorage.getItem("token");
}

function clearAuthStorage() {
  localStorage.removeItem("access_token");
  localStorage.removeItem("refresh_token");
  localStorage.removeItem("token");
  localStorage.removeItem("user");
}

